const coleta = $('Dados da coleta').first().json;
const dados = coleta.dados;
const tipo = dados.tipo_servico;

const calc = tipo === 'gravacao'
  ? $('Calcular gravação').first().json
  : $('Calcular locação').first().json;

if (calc.erro) {
  return [{ json: { erro: true, motivo: calc.motivo, telefone: coleta.telefone, cliente: coleta.nome } }];
}

  const os = $now.setZone('America/Bahia').toFormat('ddHHmm');

let conteudo = { texto: 'texto', arte: 'arte', texto_com_arte: 'texto e arte' }[dados.tipo_conteudo] || dados.tipo_conteudo;
if (dados.texto) conteudo += ` "${dados.texto}"`;
if (dados.fonte) conteudo += `, fonte ${dados.fonte}`;

const base = {
  erro: false,
  tipo,
  telefone: coleta.telefone,
  os,
  cliente: coleta.nome,
  periodo: '',
  quantidade: '', valor_unitario: '',
  dias: '', horas_dia: '', pecas_dia: '',
  distancia_km: '', valor_deslocamento: '', valor_diaria: '',
  valor_total: calc.valor_total,
  distancia_pendente: false
};

if (tipo === 'gravacao') {
  return [{ json: {
    ...base,
    referencia: `Gravação a laser - ${dados.objeto}`,
    descricao: `Gravação a laser | Objeto: ${dados.objeto} | Conteúdo: ${conteudo}`,
    quantidade: calc.quantidade,
    valor_unitario: calc.valor_unitario
  } }];
}

return [{ json: {
  ...base,
  referencia: `Locação de máquina - ${dados.localizacao}`,
  descricao: `Locação de máquina | Objeto: ${dados.objeto} | Conteúdo: ${conteudo} | Local: ${dados.localizacao}`,
  dias: calc.dias,
  horas_dia: calc.horas_por_dia,
  pecas_dia: parseInt(String(dados.pecas_por_dia).replace(/\D/g, ''), 10) || '',
  distancia_km: calc.distancia_pendente ? '' : calc.km_total,
  valor_deslocamento: calc.valor_deslocamento,
  valor_diaria: calc.valor_diaria,
  distancia_pendente: calc.distancia_pendente
} }];

const dados = $('Dados da coleta').first().json.dados;
const complexidade = 'normal'; 

const tabela = $input.all()
  .map(i => i.json)
  .map(l => ({ ...l, a_partir_de: Number(l.a_partir_de) }))
  .sort((a, b) => a.a_partir_de - b.a_partir_de);

const qtd = parseInt(String(dados.quantidade).replace(/\D/g, ''), 10);

let coluna;
if (dados.tipo_conteudo === 'texto') {
  coluna = 'texto';
} else if (dados.tipo_conteudo === 'arte') {
  coluna = complexidade === 'complexa' ? 'arte_complexa' : 'arte_normal';
} else {
  coluna = complexidade === 'complexa' ? 'arte_complexa_texto' : 'arte_normal_texto';
}

const faixa = [...tabela].reverse().find(l => qtd >= l.a_partir_de) || tabela[0];
const valorUnitario = Number(faixa[coluna]);

if (!qtd || isNaN(valorUnitario)) {
  return [{ json: { erro: true, motivo: 'Não consegui calcular: quantidade ou preço inválido', quantidade: dados.quantidade } }];
}

return [{ json: {
  erro: false,
  quantidade: qtd,
  faixa: faixa.a_partir_de,
  coluna,
  valor_unitario: valorUnitario,
  valor_total: qtd * valorUnitario
} }];

const dados = $('Dados da coleta').first().json.dados;
const preco = $input.first().json;

const extrairNumero = (texto) => {
  const m = String(texto).replace(',', '.').match(/\d+(\.\d+)?/);
  return m ? parseFloat(m[0]) : NaN;
};

const dias = extrairNumero(dados.dias_locacao);
const horas = extrairNumero(dados.horas_por_dia);
const valorHora = Number(preco.valor_hora);
const valorKm = Number(preco.valor_km);

const distanciaIdaKm  = 10;

if (isNaN(dias) || isNaN(horas) || isNaN(valorHora) || isNaN(valorKm)) {
  return [{ json: {
    erro: true,
    motivo: 'Não consegui calcular a locação: dias, horas ou preços inválidos',
    dias_locacao: dados.dias_locacao,
    horas_por_dia: dados.horas_por_dia
  } }];
}

const distanciaPendente = distanciaIdaKm === null;
const kmPorDia = distanciaPendente ? 0 : distanciaIdaKm * 2;
const kmTotal = kmPorDia * dias;          
const valorDeslocamento = kmTotal * valorKm;

const valorDiaria = horas * valorHora;
const subtotal = dias * valorDiaria;

return [{ json: {
  erro: false,
  dias,
  horas_por_dia: horas,
  valor_hora: valorHora,
  valor_diaria: valorDiaria,
  subtotal_locacao: subtotal,
  distancia_pendente: distanciaPendente,
  km_por_dia: kmPorDia,
  km_total: kmTotal,
  valor_deslocamento: valorDeslocamento,
  valor_total: subtotal + valorDeslocamento
} }];

