const msg = ($json.mensagem || '').trim();
const m = msg.match(/^(aprovar|cancelar)\s+(\S+)/i);
return [{ json: {
  valido: !!m,
  acao: m ? m[1].toLowerCase() : '',
  os: m ? m[2] : ''
} }];

